// Portfolio schedule after writes (docs/spec/05 §3.4, §3.7): a stage change recorded through the lifecycle DAL
// (prototype `advance`, logic 3922) or a project created by the New project wizard (npCreate, 3969) must move the row
// exactly as the prototype does. The oracle is `scenarios` in src/domain/pfplan.golden.json (prototype render values
// after the same change, EN and FR, generated by scripts/proto-golden-pfplan.ts). Each scenario runs on a fresh
// seeded in-memory database. L-8 (R-136): pinned to the prototype's fixed window (`from: 0`).
import { describe, expect, it, vi } from 'vitest';
vi.mock('next/headers', () => ({ cookies: async () => ({ get: () => undefined }) }));
import { portfolioScheduleModel, type PgRow } from '@/domain/pfplan';
import golden from '@/domain/pfplan.golden.json';
import { D7_PROGRESS_PCT } from '@/test/d7-cost-control';
import { makeT, type Lang } from '@/i18n/translate';
import { setDb } from '@/server/db/client';
import { stage } from '@/server/db/codes';
import { openDatabase } from '@/server/db/open';
import { recordStageChange } from '@/server/dal/lifecycle';
import { getPortfolioSchedule } from '@/server/dal/pipeline';
import { createProject } from '@/server/dal/projects';
import { PROTO } from '@/server/prototype';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = golden as any;
const TINT = { lo: 'var(--color-accent-300)', n400: 'var(--color-neutral-400)' };
const KPI_TINT = { ok: 'var(--color-text)', n200: 'var(--color-neutral-200)', lo: 'var(--color-accent-300)' };
const TAG = { accent: 'tag tag-accent', outline: 'tag tag-outline', neutral: 'tag tag-neutral' };

/** Row fields the stored data drives (windows, gates, bars, labels), as the prototype names them. */
const rowView = (r: PgRow, t: (s: string) => string) => ({
  code: r.code, name: t(`${r.displayId} · ${r.name}`), pm: t(r.pmLine), status: t(r.status), tagClass: TAG[r.tone], pipe: r.pipeline,
  segs: r.segments.map((s) => (s.kind === 'diamond' ? { left: s.left, title: t(s.title), diamond: true } : { left: s.left, width: s.width, title: t(s.title), label: s.kind === 'stage' ? t(s.label) : '' })),
  hasExec: !!r.exec, exL: r.exec?.left ?? '0', exW: r.exec?.width ?? '0', exFill: r.exec?.fill, hasBase: !!r.baseline, ...(r.baseline ? { bL: r.baseline.left, bW: r.baseline.width } : {}),
  clipText: t(r.clipText), gate: t(r.gate), gateSub: t(r.gateSub), gateColor: TINT[r.gateTint],
});
const goldenView = (g: any) => ({
  code: g.code, name: g.name, pm: g.pm, status: g.status, tagClass: g.tagClass, pipe: g.pipe,
  segs: g.segs.map((s: any) => (s.diamond ? { left: s.left, title: s.title, diamond: true } : { left: s.left, width: s.width, title: s.title, label: s.label })),
  // Delivery 7 (R-073, C-2a): the execution fill is the progress computed from the activities (src/test/d7-cost-control.ts).
  hasExec: g.hasExec, exL: g.exL, exW: g.exW, exFill: !g.pipe && g.hasExec && D7_PROGRESS_PCT[g.code] != null ? `${D7_PROGRESS_PCT[g.code]}%` : g.exFill,
  hasBase: g.hasBase, ...(g.hasBase ? { bL: g.bL, bW: g.bW } : {}),
  clipText: g.clipText, gate: g.gate, gateSub: g.gateSub, gateColor: g.gateColor,
});

async function apply(sc: any): Promise<void> {
  if (sc.create) {
    const p = sc.project;
    const code = await createProject({
      name: sc.create.name, client: sc.create.client, das: '2', machineType: 'EMP', currency: 'EUR', templateCode: 'EMP',
      categories: [{ name: 'Labor', type: 'labor', budget: p.budget }], contingencyPct: 0, calendar: 'standard_5x8',
    });
    expect(code).toBe(p.code);
  } else await recordStageChange(sc.code, stage.code(sc.to), 'auto');
}

/**
 * R-013: the golden comparison keeps the prototype's now, passed explicitly — its date (30 Sep 2026) for the DAL and its exact
 * month index (PG_NOW = 8.97, a little after 30 Sep's 8.967) for the Gantt geometry.
 */
const protoSchedule = async (zone: Parameters<typeof getPortfolioSchedule>[0]) => ({ ...(await getPortfolioSchedule(zone, '2026-09-30')), now: 8.97 });

describe('portfolio schedule after a stage change or a new project (prototype scenarios)', () => {
  it.each(Object.keys(G.scenarios))('%s', async (key) => {
    const sc = G.scenarios[key];
    setDb(await openDatabase());
    await apply(sc);
    const data = await protoSchedule(null);
    for (const lang of ['en', 'fr'] as Lang[]) {
      const t = makeT(lang);
      const want = sc[lang];
      const model = portfolioScheduleModel(data, { filter: 'all', lang, from: 0 });
      expect(model.kpis.map((k) => ({ label: t(k.label), value: t(k.value), sub: t(k.sub), color: KPI_TINT[k.tint] }))).toEqual(
        want.kpis.map((k: any) => ({ ...k, value: String(k.value) })),
      );
      expect(model.groups.map((g) => ({ key: g.key, label: t(g.label), count: g.count, codes: g.rows.map((r) => r.code) }))).toEqual(want.groups);
      for (const r of model.groups.flatMap((g) => g.rows)) {
        expect(rowView(r, t)).toEqual(goldenView(want.rows[r.code] ?? G[lang].rows[r.code]));
        // Row click (4547): the Plan of a project with planning data, else the Projects register searched by code.
        expect(r.target).toEqual(PROTO.DEFS[r.code] ? { screen: 'plan', code: r.code } : { screen: 'projects', q: r.code });
      }
    }
  }, 60_000);
});
